CREATE TABLE catalog_metadata (id INTEGER PRIMARY KEY CHECK(id=1),format_version INTEGER NOT NULL,call_count INTEGER NOT NULL CHECK(call_count>=0),total_bytes INTEGER NOT NULL CHECK(total_bytes>=0)) STRICT;
CREATE TABLE recording_system (id INTEGER PRIMARY KEY,system_key TEXT NOT NULL UNIQUE) STRICT;
CREATE TABLE recording_channel (id INTEGER PRIMARY KEY,channel_uuid TEXT NOT NULL UNIQUE) STRICT;
CREATE TABLE recording_site (id INTEGER PRIMARY KEY,wacn INTEGER NOT NULL,system_id INTEGER NOT NULL,rfss INTEGER NOT NULL,site_id INTEGER NOT NULL,UNIQUE(wacn,system_id,rfss,site_id)) STRICT;
CREATE TABLE recording_system_site (system_id INTEGER NOT NULL REFERENCES recording_system(id),site_id INTEGER NOT NULL REFERENCES recording_site(id),PRIMARY KEY(system_id,site_id)) WITHOUT ROWID, STRICT;
CREATE TABLE recording_call (id INTEGER PRIMARY KEY AUTOINCREMENT,start_ms INTEGER NOT NULL,end_ms INTEGER NOT NULL,duration_ms INTEGER NOT NULL,relative_path TEXT NOT NULL UNIQUE,size_bytes INTEGER NOT NULL,system_id INTEGER REFERENCES recording_system(id),channel_id INTEGER REFERENCES recording_channel(id),alias_list_id INTEGER,protocol INTEGER NOT NULL,call_type INTEGER NOT NULL,voice_type INTEGER NOT NULL,source_id INTEGER,source_home_wacn INTEGER,source_home_system INTEGER,source_home_id INTEGER,target_id INTEGER,target_home_wacn INTEGER,target_home_system INTEGER,target_home_id INTEGER,frequency_hz INTEGER,timeslot INTEGER,nac INTEGER,tone_kind INTEGER,tone TEXT,winner_site_id INTEGER REFERENCES recording_site(id), transcription_status TEXT NOT NULL DEFAULT 'pending' CHECK(transcription_status IN('pending','complete','failed')),CHECK(start_ms>=0 AND end_ms>=start_ms AND duration_ms>=0 AND size_bytes>0)) STRICT;
CREATE TABLE recording_call_site (call_id INTEGER NOT NULL REFERENCES recording_call(id) ON DELETE CASCADE,site_id INTEGER NOT NULL REFERENCES recording_site(id),start_ms INTEGER NOT NULL,PRIMARY KEY(call_id,site_id)) WITHOUT ROWID, STRICT;
CREATE TABLE recording_patch_member (call_id INTEGER NOT NULL REFERENCES recording_call(id) ON DELETE CASCADE,kind INTEGER NOT NULL,local_id INTEGER NOT NULL,home_wacn INTEGER NOT NULL,home_system INTEGER NOT NULL,home_id INTEGER NOT NULL,start_ms INTEGER NOT NULL,PRIMARY KEY(call_id,kind,local_id,home_wacn,home_system,home_id)) WITHOUT ROWID, STRICT;
CREATE INDEX idx_recording_call_time ON recording_call(start_ms DESC,id DESC);
CREATE INDEX idx_recording_call_system_time ON recording_call(system_id,start_ms DESC,id DESC) WHERE system_id IS NOT NULL;
CREATE INDEX idx_recording_call_channel_time ON recording_call(channel_id,start_ms DESC,id DESC) WHERE channel_id IS NOT NULL;
CREATE INDEX idx_recording_call_alias_list_time ON recording_call(alias_list_id,start_ms DESC,id DESC) WHERE alias_list_id IS NOT NULL;
CREATE INDEX idx_recording_call_target_time ON recording_call(target_id,start_ms DESC,id DESC) WHERE target_id IS NOT NULL;
CREATE INDEX idx_recording_call_source_time ON recording_call(source_id,start_ms DESC,id DESC) WHERE source_id IS NOT NULL;
CREATE INDEX idx_recording_call_frequency_time ON recording_call(frequency_hz,start_ms DESC,id DESC) WHERE frequency_hz IS NOT NULL;
CREATE INDEX idx_recording_call_site_lookup ON recording_call_site(site_id,start_ms DESC,call_id DESC);
CREATE INDEX idx_recording_patch_member_lookup ON recording_patch_member(kind,local_id,start_ms DESC,call_id DESC);
CREATE TABLE recording_transcript (call_id INTEGER PRIMARY KEY REFERENCES recording_call(id) ON DELETE CASCADE,text TEXT NOT NULL,stored_at_ms INTEGER NOT NULL CHECK(stored_at_ms>=0)) STRICT;
CREATE INDEX idx_recording_call_transcription_pending ON recording_call(id,duration_ms) WHERE transcription_status='pending';
CREATE TABLE recording_tone_sequence (call_id INTEGER PRIMARY KEY REFERENCES recording_call(id) ON DELETE CASCADE,source_code INTEGER NOT NULL CHECK(source_code IN(1,2)),method_code INTEGER NOT NULL CHECK(method_code IN(1,2,3,4)),phase INTEGER CHECK(phase IS NULL OR phase IN(1,2)),call_started_at_ms INTEGER NOT NULL CHECK(call_started_at_ms>0),first_voice_sample_at_ms INTEGER CHECK(first_voice_sample_at_ms IS NULL OR first_voice_sample_at_ms>0),completed_at_ms INTEGER NOT NULL CHECK(completed_at_ms>=call_started_at_ms),tone_count INTEGER NOT NULL CHECK(tone_count BETWEEN 1 AND 32),CHECK((source_code=1 AND method_code IN(1,3,4)) OR (source_code=2 AND method_code=2))) STRICT;
CREATE TABLE recording_tone (call_id INTEGER NOT NULL REFERENCES recording_tone_sequence(call_id) ON DELETE CASCADE,ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 31),frequency_1_millihz INTEGER CHECK(frequency_1_millihz IS NULL OR frequency_1_millihz BETWEEN 1 AND 8000000),frequency_2_millihz INTEGER CHECK(frequency_2_millihz IS NULL OR frequency_2_millihz BETWEEN 1 AND 8000000),codec_symbol TEXT CHECK(codec_symbol IS NULL OR (length(codec_symbol) BETWEEN 1 AND 64 AND codec_symbol NOT GLOB '*[^A-Z0-9_]*')),offset_ms INTEGER CHECK(offset_ms IS NULL OR offset_ms>=0),duration_ms INTEGER NOT NULL CHECK(duration_ms>0),confidence_ppm INTEGER CHECK(confidence_ppm IS NULL OR confidence_ppm BETWEEN 0 AND 1000000),PRIMARY KEY(call_id,ordinal),CHECK(frequency_2_millihz IS NULL OR frequency_1_millihz IS NOT NULL),CHECK(frequency_1_millihz IS NOT NULL OR codec_symbol IS NOT NULL)) WITHOUT ROWID, STRICT;
CREATE INDEX idx_recording_call_unowned_time ON recording_call(start_ms DESC,id DESC) WHERE system_id IS NULL;
CREATE INDEX idx_recording_call_source_home_time ON recording_call(source_home_wacn,source_home_system,source_home_id,start_ms DESC,id DESC,system_id) WHERE source_home_id IS NOT NULL;
CREATE INDEX idx_recording_call_target_home_time ON recording_call(target_home_wacn,target_home_system,target_home_id,start_ms DESC,id DESC,call_type,system_id) WHERE target_home_id IS NOT NULL;
CREATE INDEX idx_recording_patch_member_home_lookup ON recording_patch_member(kind,home_wacn,home_system,home_id,start_ms DESC,call_id DESC,local_id);
CREATE INDEX idx_recording_call_protocol_time ON recording_call(protocol,start_ms DESC,id DESC);
CREATE INDEX idx_recording_call_call_type_time ON recording_call(call_type,start_ms DESC,id DESC);
CREATE INDEX idx_recording_call_voice_type_time ON recording_call(voice_type,start_ms DESC,id DESC);
