CREATE TABLE recording_identifier (call_id INTEGER NOT NULL REFERENCES recording_call(id) ON DELETE CASCADE,protocol TEXT NOT NULL CHECK(protocol IN('DCS','FLEETSYNC','MDC1200','LOJACK','TAIT1200')),kind TEXT NOT NULL CHECK(kind IN('radio','tone','function')),role TEXT NOT NULL CHECK(role IN('source','destination','other')),value TEXT NOT NULL CHECK(length(value) BETWEEN 1 AND 128 AND length(trim(value))>0 AND instr(value,char(0))=0),start_ms INTEGER NOT NULL CHECK(start_ms>=0),PRIMARY KEY(call_id,protocol,kind,role,value),CHECK((protocol='DCS' AND kind='tone') OR (protocol IN('FLEETSYNC','MDC1200','TAIT1200') AND kind='radio') OR (protocol='LOJACK' AND kind IN('radio','function')))) WITHOUT ROWID, STRICT;
CREATE INDEX idx_recording_identifier_lookup ON recording_identifier(protocol,kind,value,start_ms DESC,call_id DESC,role);
INSERT INTO recording_identifier VALUES(41,'TAIT1200','radio','source','UNIT-A',1000),(42,'DCS','tone','other','N023',2000);
CREATE VIRTUAL TABLE recording_transcript_fts USING fts5(text,content='recording_transcript',content_rowid='call_id',tokenize='unicode61');
CREATE TRIGGER recording_transcript_fts_insert AFTER INSERT ON recording_transcript BEGIN INSERT INTO recording_transcript_fts(rowid,text) VALUES(new.call_id,new.text); END;
CREATE TRIGGER recording_transcript_fts_delete AFTER DELETE ON recording_transcript BEGIN INSERT INTO recording_transcript_fts(recording_transcript_fts,rowid,text) VALUES('delete',old.call_id,old.text); END;
CREATE TRIGGER recording_transcript_fts_update AFTER UPDATE ON recording_transcript BEGIN INSERT INTO recording_transcript_fts(recording_transcript_fts,rowid,text) VALUES('delete',old.call_id,old.text); INSERT INTO recording_transcript_fts(rowid,text) VALUES(new.call_id,new.text); END;
INSERT INTO recording_transcript_fts(recording_transcript_fts) VALUES('rebuild');
